/**  One file in a course subfolder. */
export type CourseFile = {
	/**  The file name, e.g. `07-covariance.pdf`. */
	name: string,
	/**  The path relative to the course root with `/` separators, e.g. `slides/07-covariance.pdf`. */
	path: string,
};

/**  An opened course folder and the files in its `lectures/` and `slides/`. */
export type CourseListing = {
	/**  Canonical absolute path. */
	path: string,
	/**  The folder's own name. */
	name: string,
	/**  The lecture files (`lectures/*.md`), by name. */
	lectures: CourseFile[],
	/**  The slide files (`slides/*`), by name. */
	slides: CourseFile[],
};

/**
 *  `course_open`'s result: the folder the user picked, its listing (the same JSON the
 *  command-line harness prints for `course open`) and whether trust is still to be asked.
 */
export type CourseOpened = {
	trust: Trust,
} & CourseListing;

/**
 *  One edit from the buffer: replace `from..to` with `text`. Positions are UTF-16 code units
 *  into the document as of the previous edit (CodeMirror's positions).
 */
export type Edit = {
	/**  The first position replaced. */
	from: number,
	/**  The position after the last one replaced; `from` for an insert. */
	to: number,
	/**  The new text; empty for a delete. */
	text: string,
};

/**
 *  What kind of failure an IPC command (or a harness call) reports. On the wire it is the code's
 *  string, e.g. `"E_INVALID_ARGUMENT"`.
 */
