/**  Spend cap reached. */
"E_BUDGET" | 
/**  Timed out. */
"E_TIMEOUT" | 
/**  Other provider error (5xx, malformed). */
"E_PROVIDER" | 
/**  User or shutdown cancelled. */
"E_CANCELLED" | 
/**  Model lacks a capability. */
"E_UNSUPPORTED" | 
/**  Bug. */
"E_INTERNAL";

